WITH exploded AS (SELECT id, coupon_codes, INLINE(items) FROM carts) SELECT price, promo, DENSE_RANK() OVER w_part AS qty_dense_rank, ROUND(qty / SUM(qty) OVER (PARTITION BY promo), 4) AS qty_share, PERCENT_RANK() OVER (ORDER BY qty DESC NULLS LAST) AS qty_percent_rank FROM exploded WHERE promo IN ('WELCOME5', 'SPRING10', 'BUNDLE') WINDOW w_part AS (PARTITION BY promo ORDER BY qty);
